html:
{% set company_name = frappe.db.get_single_value('Global Defaults', 'default_company') or '' %}
{% set report_title = doc.report_title or doc.name %}
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>{{ report_title }}</title>
    <style>
        @page {
            size: A4;
            margin: 16mm 14mm 18mm 14mm;
        }

        body {
            font-family: "Segoe UI", Arial, Helvetica, sans-serif;
            color: #1f2937;
            font-size: 11px;
            line-height: 1.45;
            margin: 0;
            padding: 0;
            background: #ffffff;
        }

        .page-break { page-break-after: always; }
        .avoid-break { page-break-inside: avoid; }

        .cover {
            min-height: 92vh;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            border: 1px solid #d8e1ea;
            padding: 28px 30px;
            background: linear-gradient(180deg, #f6f9fc 0%, #ffffff 55%);
        }

        .cover-topbar {
            height: 8px;
            background: linear-gradient(90deg, #12344d 0%, #1f4e78 55%, #6c8aa6 100%);
            margin: -28px -30px 30px -30px;
        }

        .brand-block {
            margin-bottom: 24px;
        }

        .brand-line {
            font-size: 12px;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: #5b7083;
            margin-bottom: 10px;
        }

        .cover-title {
            font-size: 34px;
            line-height: 1.15;
            font-weight: 800;
            color: #102a43;
            margin: 0 0 8px 0;
        }

        .cover-subtitle {
            font-size: 15px;
            color: #486581;
            margin: 0 0 24px 0;
        }

        .cover-pill {
            display: inline-block;
            padding: 6px 12px;
            border: 1px solid #c9d6e2;
            border-radius: 999px;
            font-size: 11px;
            color: #12344d;
            background: #ffffff;
            margin-right: 6px;
            margin-bottom: 6px;
            font-weight: 600;
        }

        .cover-meta {
            width: 100%;
            border-collapse: collapse;
            margin-top: 18px;
        }

        .cover-meta td {
            padding: 10px 12px;
            border: 1px solid #d9e2ec;
            vertical-align: top;
        }

        .cover-meta .label {
            width: 23%;
            background: #f7fafc;
            color: #334e68;
            font-weight: 700;
        }

        .cover-bottom {
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            margin-top: 32px;
        }

        .cover-note {
            font-size: 11px;
            color: #52606d;
            max-width: 62%;
        }

        .report-code {
            text-align: right;
            font-size: 11px;
            color: #52606d;
        }

        .content-header {
            border-bottom: 3px solid #1f4e78;
            padding-bottom: 10px;
            margin-bottom: 18px;
        }

        .content-title {
            font-size: 24px;
            font-weight: 800;
            color: #102a43;
            margin: 0 0 4px 0;
        }

        .content-subtitle {
            font-size: 12px;
            color: #627d98;
            margin: 0;
        }

        .section {
            margin-top: 18px;
        }

        .section-title {
            font-size: 15px;
            font-weight: 800;
            color: #102a43;
            margin: 0 0 10px 0;
            padding: 0 0 7px 0;
            border-bottom: 1px solid #d9e2ec;
            letter-spacing: 0.2px;
        }

        .summary-grid {
            width: 100%;
            border-collapse: separate;
            border-spacing: 8px;
            margin: 0 -8px;
        }

        .summary-card {
            border: 1px solid #d9e2ec;
            background: linear-gradient(180deg, #f9fbfd 0%, #ffffff 100%);
            border-radius: 8px;
            text-align: center;
            padding: 14px 10px;
        }

        .summary-value {
            display: block;
            font-size: 24px;
            font-weight: 800;
            color: #1f4e78;
            line-height: 1.1;
            margin-bottom: 4px;
        }

        .summary-label {
            display: block;
            font-size: 10px;
            color: #627d98;
            text-transform: uppercase;
            letter-spacing: 0.7px;
            font-weight: 700;
        }

        .meta-table, .engagement-table, .detail-table {
            width: 100%;
            border-collapse: collapse;
        }

        .meta-table td,
        .engagement-table th, .engagement-table td,
        .detail-table th, .detail-table td {
            border: 1px solid #d9e2ec;
            padding: 8px 9px;
            vertical-align: top;
        }

        .meta-table .label {
            width: 20%;
            background: #f7fafc;
            font-weight: 700;
            color: #334e68;
        }

        .engagement-table th,
        .detail-table th {
            background: #eef4f8;
            color: #102a43;
            font-weight: 800;
            text-align: left;
        }

        .narrative {
            border: 1px solid #d9e2ec;
            background: #ffffff;
            padding: 12px 13px;
            min-height: 54px;
        }

        .board-banner {
            background: linear-gradient(90deg, #12344d 0%, #1f4e78 60%, #486581 100%);
            color: #ffffff;
            padding: 12px 14px;
            border-radius: 6px 6px 0 0;
            font-weight: 700;
            font-size: 12px;
            text-transform: uppercase;
            letter-spacing: 0.8px;
        }

        .board-panel {
            border: 1px solid #d9e2ec;
            border-top: 0;
            padding: 14px;
            background: #ffffff;
        }

        .chip {
            display: inline-block;
            padding: 3px 9px;
            border-radius: 999px;
            border: 1px solid #cfd8e3;
            background: #ffffff;
            color: #334e68;
            font-size: 10px;
            font-weight: 700;
            margin-right: 6px;
            margin-bottom: 4px;
        }

        .finding-card {
            border: 1px solid #d9e2ec;
            border-radius: 8px;
            margin-bottom: 16px;
            overflow: hidden;
            background: #ffffff;
        }

        .finding-head {
            padding: 12px 14px;
            background: linear-gradient(180deg, #f8fbfd 0%, #eef4f8 100%);
            border-bottom: 1px solid #d9e2ec;
        }

        .finding-index {
            font-size: 10px;
            text-transform: uppercase;
            color: #627d98;
            letter-spacing: 0.8px;
            margin-bottom: 4px;
            font-weight: 700;
        }

        .finding-title {
            margin: 0 0 6px 0;
            font-size: 15px;
            color: #102a43;
            font-weight: 800;
            line-height: 1.3;
        }

        .finding-body {
            padding: 12px 14px;
        }

        .detail-table .label {
            width: 19%;
            background: #fafbfd;
            font-weight: 700;
            color: #334e68;
        }

        .severity-high { color: #9b1c1c; }
        .severity-medium { color: #8a5a00; }
        .severity-low { color: #166534; }

        .footer {
            margin-top: 22px;
            padding-top: 10px;
            border-top: 1px solid #d9e2ec;
            font-size: 10px;
            color: #7b8794;
            text-align: center;
        }

        .muted { color: #627d98; }
    </style>
</head>
<body>

    <div class="cover">
        <div>
            <div class="cover-topbar"></div>

            <div class="brand-block">
                <div class="brand-line">Confidential Board Submission</div>
                <h1 class="cover-title">{{ report_title }}</h1>
                <p class="cover-subtitle">Audit report prepared for executive and board-level review.</p>

                <div>
                    <span class="cover-pill">Audit Report</span>
                    {% if doc.report_status or doc.status %}
                    <span class="cover-pill">{{ doc.report_status or doc.status }}</span>
                    {% endif %}
                    {% if doc.audit_plan %}
                    <span class="cover-pill">{{ doc.audit_plan }}</span>
                    {% endif %}
                </div>
            </div>

            <table class="cover-meta">
                <tr>
                    <td class="label">Report ID</td>
                    <td>{{ doc.name }}</td>
                    <td class="label">Report Date</td>
                    <td>{{ frappe.utils.formatdate(doc.report_date) if doc.report_date else '' }}</td>
                </tr>
                <tr>
                    <td class="label">Audit Plan</td>
                    <td>{{ doc.audit_plan or '' }}</td>
                    <td class="label">Prepared By</td>
                    <td>{{ doc.prepared_by or '' }}</td>
                </tr>
                <tr>
                    <td class="label">Reviewed By</td>
                    <td>{{ doc.reviewed_by or '' }}</td>
                    <td class="label">Company</td>
                    <td>{{ company_name }}</td>
                </tr>
            </table>
        </div>

        <div class="cover-bottom">
            <div class="cover-note">
                This report consolidates the audit scope, key observations, associated management actions, and remediation status for the referenced engagement(s).
            </div>
            <div class="report-code">
                <strong>{{ doc.name }}</strong><br>
                Generated on {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}
            </div>
        </div>
    </div>

    <div class="page-break"></div>

    <div class="content-header">
        <h2 class="content-title">{{ report_title }}</h2>
        <p class="content-subtitle">Board Summary and Detailed Audit Observations</p>
    </div>

    <div class="section avoid-break">
        <h3 class="section-title">Board Dashboard</h3>
        <table class="summary-grid">
            <tr>
                <td class="summary-card">
                    <span class="summary-value">{{ doc.total_findings or 0 }}</span>
                    <span class="summary-label">Total Findings</span>
                </td>
                <td class="summary-card">
                    <span class="summary-value">{{ doc.high_severity_findings or 0 }}</span>
                    <span class="summary-label">High Severity</span>
                </td>
                <td class="summary-card">
                    <span class="summary-value">{{ doc.medium_severity_findings or 0 }}</span>
                    <span class="summary-label">Medium Severity</span>
                </td>
                <td class="summary-card">
                    <span class="summary-value">{{ doc.low_severity_findings or 0 }}</span>
                    <span class="summary-label">Low Severity</span>
                </td>
                <td class="summary-card">
                    <span class="summary-value">{{ doc.open_capas or 0 }}</span>
                    <span class="summary-label">Open CAPAs</span>
                </td>
                <td class="summary-card">
                    <span class="summary-value">{{ doc.overdue_capas or 0 }}</span>
                    <span class="summary-label">Overdue CAPAs</span>
                </td>
            </tr>
        </table>
    </div>

    <div class="section avoid-break">
        <div class="board-banner">Executive Summary</div>
        <div class="board-panel">
            {{ doc.executive_summary or '' }}
        </div>
    </div>

    <div class="section">
        <h3 class="section-title">Scope, Objectives and Conclusion</h3>
        <table class="meta-table">
            <tr>
                <td class="label">Scope of Review</td>
                <td>{{ doc.scope_of_review or '' }}</td>
            </tr>
            <tr>
                <td class="label">Audit Objectives</td>
                <td>{{ doc.audit_objectives or '' }}</td>
            </tr>
            <tr>
                <td class="label">Methodology</td>
                <td>{{ doc.methodology or '' }}</td>
            </tr>
            {% if doc.management_response_summary %}
            <tr>
                <td class="label">Management Response Summary</td>
                <td>{{ doc.management_response_summary }}</td>
            </tr>
            {% endif %}
            {% if doc.capa_summary %}
            <tr>
                <td class="label">CAPA Summary</td>
                <td>{{ doc.capa_summary }}</td>
            </tr>
            {% endif %}
            {% if doc.high_priority_actions %}
            <tr>
                <td class="label">High Priority Actions</td>
                <td>{{ doc.high_priority_actions }}</td>
            </tr>
            {% endif %}
            <tr>
                <td class="label">Overall Conclusion</td>
                <td>{{ doc.overall_conclusion or '' }}</td>
            </tr>
        </table>
    </div>

    <div class="section">
        <h3 class="section-title">Referenced Engagements</h3>
        <table class="engagement-table">
            <thead>
                <tr>
                    <th style="width:7%;">#</th>
                    <th style="width:48%;">Engagement</th>
                    <th style="width:20%;">Status</th>
                    <th style="width:25%;">Reference</th>
                </tr>
            </thead>
            <tbody>
                {% if doc.engagements %}
                    {% for row in doc.engagements %}
                    <tr>
                        <td>{{ loop.index }}</td>
                        <td>{{ row.engagement or row.audit_engagement or '' }}</td>
                        <td>{{ row.status or '' }}</td>
                        <td>{{ row.name or '' }}</td>
                    </tr>
                    {% endfor %}
                {% else %}
                    <tr>
                        <td colspan="4" class="muted">No engagement references added.</td>
                    </tr>
                {% endif %}
            </tbody>
        </table>
    </div>

    <div class="section">
        <h3 class="section-title">Detailed Findings</h3>
        {% if doc.group_findings_by and doc.group_findings_by != 'None' %}
            <div class="muted" style="margin-bottom:8px;">Grouped by: {{ doc.group_findings_by }}</div>
        {% endif %}

        {% if doc.findings %}
            {% for f in doc.findings %}
                {% set sev = (f.severity or '')|lower %}
                <div class="finding-card avoid-break">
                    <div class="finding-head">
                        <div class="finding-index">Finding {{ loop.index }}</div>
                        <h4 class="finding-title">{{ f.finding_title or f.title or f.finding or 'Finding' }}</h4>
                        <div>
                            <span class="chip {% if sev == 'high' %}severity-high{% elif sev == 'medium' %}severity-medium{% elif sev == 'low' %}severity-low{% endif %}">
                                Severity: {{ f.severity or '' }}
                            </span>
                            {% if f.finding_status %}<span class="chip">Finding Status: {{ f.finding_status }}</span>{% endif %}
                            {% if f.capa_status %}<span class="chip">CAPA Status: {{ f.capa_status }}</span>{% endif %}
                            {% if f.audit_engagement %}<span class="chip">Engagement: {{ f.audit_engagement }}</span>{% endif %}
                            {% if f.related_process %}<span class="chip">Process: {{ f.related_process }}</span>{% endif %}
                            {% if f.is_capa_overdue %}<span class="chip severity-high">CAPA Overdue</span>{% endif %}
                        </div>
                    </div>
                    <div class="finding-body">
                        <table class="detail-table">
                            <tr>
                                <td class="label">Description</td>
                                <td>{{ f.description or '' }}</td>
                            </tr>
                            <tr>
                                <td class="label">Cause</td>
                                <td>{{ f.cause or '' }}</td>
                            </tr>
                            <tr>
                                <td class="label">Impact</td>
                                <td>{{ f.impact or '' }}</td>
                            </tr>
                            <tr>
                                <td class="label">Recommendation</td>
                                <td>{{ f.recommendation or '' }}</td>
                            </tr>
                            <tr>
                                <td class="label">Management Owner</td>
                                <td>{{ f.management_owner or '' }}</td>
                            </tr>
                            <tr>
                                <td class="label">Target Closure Date</td>
                                <td>{{ frappe.utils.formatdate(f.target_closure_date) if f.target_closure_date else '' }}</td>
                            </tr>
                            {% if f.related_risks %}
                            <tr>
                                <td class="label">Related Risks</td>
                                <td>{{ f.related_risks }}</td>
                            </tr>
                            {% endif %}
                            {% if f.related_controls %}
                            <tr>
                                <td class="label">Related Controls</td>
                                <td>{{ f.related_controls }}</td>
                            </tr>
                            {% endif %}
                        </table>
                    </div>
                </div>
            {% endfor %}
        {% else %}
            <div class="narrative muted">No findings added to this report.</div>
        {% endif %}
    </div>

    <div class="footer">
        Confidential internal document. Generated from Audit Management System on {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}.
    </div>
</body>
</html>
